//! Simple case folding for `fold(text)` (docs/lists.md section 10, #37).
//!
//! One table, [`FOLD_RANGES`] (generated by `scripts/gen_casefold.py` from Unicode's CaseFolding statuses C and S), is the
//! only source of the folding in both runtimes: replay calls [`fold_text`], and the emitted JavaScript is handed the very
//! same ranges ([`js_ranges`]). Neither runtime consults its own library (`toLowerCase`, `to_lowercase`), which disagree
//! on `İ` and on a final sigma, so a page and its replay cannot disagree here.

mod table {
    include!("casefold_table.rs");
}

pub use table::{FOLD_RANGES, UNICODE_VERSION};

/// The folded code point: itself when it is not in the table. Binary search over the runs, which are sorted and do not
/// overlap (the generator asserts it and `the_table_is_sorted_and_disjoint` checks it).
pub fn fold_char(c: char) -> char {
    let cp = c as u32;
    let idx = FOLD_RANGES.partition_point(|&(_, hi, _, _)| hi < cp);
    if let Some(&(lo, hi, delta, stride)) = FOLD_RANGES.get(idx)
        && cp >= lo
        && cp <= hi
        && (cp - lo).is_multiple_of(stride)
    {
        let folded = (cp as i64 + delta as i64) as u32;
        // The table maps scalar values to scalar values; a result that is not one leaves the character alone.
        return char::from_u32(folded).unwrap_or(c);
    }
    c
}

/// `fold(text)`: every character folded, one for one.
pub fn fold_text(text: &str) -> String {
    text.chars().map(fold_char).collect()
}

/// The ranges as the flat JavaScript array literal `[lo, hi, delta, stride, lo, hi, ...]` the emitted `__cui_fold` reads.
pub fn js_ranges() -> String {
    let mut out = String::from("[");
    for (i, (lo, hi, delta, stride)) in FOLD_RANGES.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(&format!("{lo},{hi},{delta},{stride}"));
    }
    out.push(']');
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_table_is_sorted_and_disjoint() {
        let mut prev_hi = 0u32;
        for (i, &(lo, hi, _, stride)) in FOLD_RANGES.iter().enumerate() {
            assert!(lo <= hi && stride >= 1, "run {i}");
            assert!(i == 0 || lo > prev_hi, "run {i} overlaps the one before");
            prev_hi = hi;
        }
    }

    #[test]
    fn the_cases_the_standard_names() {
        assert_eq!(fold_char('\u{1E9E}'), '\u{DF}'); // capital sharp s -> eszett (S)
        assert_eq!(fold_char('\u{DF}'), '\u{DF}'); // the eszett has only a full fold
        assert_eq!(fold_char('\u{130}'), '\u{130}'); // dotted capital I: only the Turkic and full folds
        assert_eq!(fold_char('\u{131}'), '\u{131}');
        assert_eq!(fold_char('I'), 'i');
        assert_eq!(fold_char('\u{3C2}'), '\u{3C3}'); // final sigma -> sigma
        assert_eq!(fold_char('\u{1F88}'), '\u{1F80}'); // S
        assert_eq!(fold_char('\u{13F8}'), '\u{13F0}'); // Cherokee small -> capital
        assert_eq!(fold_char('\u{10400}'), '\u{10428}'); // astral
    }

    #[test]
    fn folding_twice_is_folding_once() {
        for cp in 0..=0x10FFFFu32 {
            if let Some(c) = char::from_u32(cp) {
                assert_eq!(fold_char(fold_char(c)), fold_char(c), "{cp:#X}");
            }
        }
    }
}
